def out(lang):
    books = json.load(open(f'src/locales/content/{lang}.json'))['books'] if lang != 'ar' else {}
    d = {'translation': {'status': 'draft'}, 'verification': {'status': 'PENDING_REVIEW'},
         'title': TITLE[lang], 'subtitle': SUB[lang], 'sections': {k: v[lang] for k, v in SECTIONS.items()},
         'facts': {k: {'label': v[0][lang], 'value': v[1][lang]} for k, v in FACTS.items()},
         'claims': {k: v[lang] for k, v in CLAIMS.items()},
         'journey': {k: {'label': v[0][lang], 'when': v[1][lang]} for k, v in JOURNEY.items()},
         'refs': {k: v[lang] for k, v in REFS.items() if v[lang]}, 'books': books}
    if lang == 'ar': del d['translation']
    json.dump(d, open(f'src/bio/abubakr/{lang}.json', 'w'), ensure_ascii=False, indent=2); open(f'src/bio/abubakr/{lang}.json', 'a').write('\n')
for l in L: out(l)
print('ok', len(CLAIMS), 'claims')
